      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-audit\",\n  \"version\": \"0.5.2\",\n  \"description\": \"Ecosystem-wide plugin health audit for DeepSeek Harness: syncs the GitHub dsh-plugin topic into a local catalog, probes npm, static-scans plugin files for security, scores every plugin (maintenance / docs / npm / ecosystem + security veto), keeps score history with movers, and exposes a web leaderboard plus agent tools.\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./audit\": \"./lib/audit.js\",\n    \"./scoring\": \"./lib/scoring.js\",\n    \"./storage\": \"./lib/storage.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"cordis.patch.yml\",\n    \"data\",\n    \"README.md\",\n    \"README.zh.md\",\n    \"ROADMAP.md\"\n  ],\n  \"scripts\": {\n    \"test\": \"node test/audit.test.mjs && node test/probe.test.mjs && node test/scanner.test.mjs && node test/scoring.test.mjs && node test/security.test.mjs && node test/storage.test.mjs && node test/trend-scan.test.mjs && node test/trend.test.mjs\",\n    \"seed\": \"node scripts/seed.mjs\",\n    \"sync:local\": \"node scripts/sync.mjs\"\n  },\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh\",\n    \"dsh-plugin\",\n    \"cordis\",\n    \"plugin\",\n    \"audit\",\n    \"health\",\n    \"quality\",\n    \"marketplace\",\n    \"vetting\"\n  ],\n  \"license\": \"MIT\",\n  \"dependencies\": {},\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-runtime\",\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-conversation\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-agent\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-locale\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-runtime\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-fs\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-llm\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-session\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-session-projection\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-system-prompt\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-tools\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/schemastery\": \"^3.18.1\",\n    \"react\": \"^18.2.0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh-client-locale\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-runtime\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-conversation\": {\n      \"optional\": true\n    },\n    \"react\": {\n      \"optional\": true\n    }\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/863683348/dsh-plugin-audit.git\"\n  },\n  \"homepage\": \"https://github.com/863683348/dsh-plugin-audit#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/863683348/dsh-plugin-audit/issues\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  }\n}\n"
