      "path": "lib/security.js",
      "content": "/**\n * dsh-plugin-audit — static security heuristics (v0.2).\n *\n * Pure text scanners over the files a plugin ships: package.json install\n * scripts, shell scripts, and JS entry sources. Every rule returns\n * { id, severity, detail } findings; severity ∈ info|medium|high|critical.\n *\n * Design rules:\n *   - Static only, deterministic, no code execution — findings are evidence\n *     for a human reviewer, never a final verdict.\n *   - High/critical findings veto the grade (scoreRecord pushes them into\n *     `flags` → grade D), medium/low/info just lower the trust score.\n *   - Allowlisted domains never fire the network-callback rule.\n *\n * The scanner is deliberately conservative: false negatives are acceptable,\n * false positives erode trust. When in doubt, report with lower severity.\n */\n\n/** Domains a plugin may legitimately talk to without review. */\nexport const NET_ALLOWLIST = [\n  \"api.github.com\", \"raw.githubusercontent.com\", \"registry.npmjs.org\",\n  \"github.com\", \"api.deepseek.com\", \"deepseek.com\", \"localhost\", \"127.0.0.1\",\n  \"0.0.0.0\", \"::1\",\n];\n\nconst SEVERITY_WEIGHT = { critical: 40, high: 20, medium: 8, low: 3, info: 1 };\n\n/** Run a regex over text and return a finding detail or null. */\nfunction find(patterns, text) {\n  for (const re of patterns) {\n    const m = re.exec(text);\n    if (m) return m[0].slice(0, 120);\n  }\n  return null;\n}\n\n/** Network exfiltration: suspicious domains outside the allowlist. */\nexport function scanNetworkUrls(text, path) {\n  const findings = [];\n  const re = /(?:fetch\\(\\s*[\"']|https?:\\/\\/)([a-zA-Z0-9.-]+\\.[a-z]{2,})(?:[\\/\"']|\\s)/g;\n  let m;\n  const seen = new Set();\n  while ((m = re.exec(text)) !== null) {\n    const host = m[1].toLowerCase();\n    if (NET_ALLOWLIST.some((d) => host === d || host.endsWith(\".\" + d))) continue;\n    if (seen.has(host)) continue;\n    seen.add(host);\n    findings.push({\n      rule: \"net-callback\",\n      severity: host.includes(\"telegram\") || host.includes(\"t.me\") || host.includes(\"discord\") ? \"high\" : \"medium\",\n      detail: \"network call to non-allowlisted host: \" + host + \" (\" + path + \")\",\n    });\n  }\n  return findings;\n}\n\n/** package.json install scripts + shell lines. */\nexport function scanManifest(text, path = \"package.json\") {\n  const findings = [];\n  let pkg = null;\n  try {\n    pkg = JSON.parse(text);\n  } catch {\n    findings.push({ rule: \"manifest-invalid\", severity: \"medium\", detail: \"package.json is not valid JSON (\" + path + \")\" });\n    return findings;\n  }\n  const scripts = pkg?.scripts ?? {};\n  const installish = Object.entries(scripts).filter(([k]) =>\n    /^(preinstall|install|postinstall|prepare|prepublish|prepublishOnly|postinstall)$/i.test(k));\n  for (const [k, body] of installish) {\n    if (typeof body !== \"string\" || body.length === 0) continue;\n    const s = body;\n    if (find([/(?:curl|wget)[^;|&]*\\|\\s*(?:ba)?sh\\b/i], s)) {\n      findings.push({ rule: \"pipe-remote-to-shell\", severity: \"critical\", detail: k + \" pipes a remote fetch into a shell: \" + s.slice(0, 100) });\n    }\n    if (find([/curl[^;|&]*(?:-o|-O|--output)\\s+[^;|&]+[;|&]\\s*[^;|&]*sh\\b/i, /wget[^;|&]*(?:-O|--output-document)\\s+[^;|&]+[;|&]\\s*[^;|&]*sh\\b/i], s)) {\n      findings.push({ rule: \"download-then-exec\", severity: \"high\", detail: k + \" downloads then executes: \" + s.slice(0, 100) });\n    }\n    if (find([/base64\\s*-d[^;|&]*\\|\\s*(?:ba)?sh\\b/i, /powershell[^;|&]*(?:-enc|\\s-e\\s)/i, /-e\\s+[A-Za-z0-9+/=]{40,}/i], s)) {\n      findings.push({ rule: \"encoded-command\", severity: \"critical\", detail: k + \" decodes an encoded command: \" + s.slice(0, 100) });\n    }\n    if (find([/\\beval\\b/i, /\\bsh\\s+-c\\b/i], s)) {\n      findings.push({ rule: \"eval-in-script\", severity: \"high\", detail: k + \" evaluates a command string: \" + s.slice(0, 100) });\n    }\n    if (find([/~\\/\\.(?:bashrc|zshrc|profile|bash_profile|zprofile)/i, /\\.bashrc|\\/\\.zshrc/], s)) {\n      findings.push({ rule: \"rc-persistence\", severity: \"critical\", detail: k + \" writes to a shell rc file (persistence): \" + s.slice(0, 100) });\n    }\n    if (find([/\\bchmod\\s+[+]?x\\b/], s)) {\n      findings.push({ rule: \"chmod-exec\", severity: \"medium\", detail: k + \" chmods a file executable: \" + s.slice(0, 100) });\n    }\n    findings.push({ rule: \"install-script\", severity: \"medium\", detail: k + \" runs code at install time: \" + s.slice(0, 100) });\n  }\n  return findings;\n}\n\n/** Shell scripts: persistence, remote exec, obfuscation. */\nexport function scanShell(text, path) {\n  const findings = [];\n  if (find([/(?:curl|wget)[^;|&]*\\|\\s*(?:ba)?sh\\b/i], text)) {\n    findings.push({ rule: \"pipe-remote-to-shell\", severity: \"critical\", detail: \"pipes a remote fetch into a shell (\" + path + \")\" });\n  }\n  if (find([/base64\\s*-d[^;|&]*\\|\\s*(?:ba)?sh\\b/i, /-e\\s+[A-Za-z0-9+/=]{40,}/i, /powershell[^;|&]*(?:-enc|\\s-e\\s)/i], text)) {\n    findings.push({ rule: \"encoded-command\", severity: \"critical\", detail: \"decodes an encoded command (\" + path + \")\" });\n  }\n  if (find([/~\\/\\.(?:bashrc|zshrc|profile|bash_profile|zprofile)/i], text)) {\n    findings.push({ rule: \"rc-persistence\", severity: \"critical\", detail: \"writes to a shell rc file (\" + path + \")\" });\n  }\n  if (find([/\\beval\\b/i, /\\bsh\\s+-c\\b/i], text)) {\n    findings.push({ rule: \"eval-in-script\", severity: \"high\", detail: \"evaluates a command string (\" + path + \")\" });\n  }\n  const urls = scanNetworkUrls(text, path);\n  findings.push(...urls);\n  return findings;\n}\n\n/** JS sources: dynamic code, child processes, env exfiltration, obfuscation. */\nexport function scanSource(text, path) {\n  const findings = [];\n  if (find([/\\beval\\s*\\(/i], text)) {\n    findings.push({ rule: \"eval\", severity: \"high\", detail: \"eval() in source (\" + path + \")\" });\n  }\n  if (find([/new\\s+Function\\s*\\(/i, /Function\\s*\\(\\s*[\"']/i], text)) {\n    findings.push({ rule: \"dynamic-code\", severity: \"medium\", detail: \"dynamic code construction (\" + path + \")\" });\n  }\n  if (find([/(?:child_process\\.(?:exec|execSync|spawn|spawnSync))|(?:require\\([\"']child_process[\"']\\))/i], text)) {\n    findings.push({ rule: \"child-process\", severity: \"medium\", detail: \"spawns child processes (\" + path + \")\" });\n  }\n  if (find([/atob\\s*\\([^)]{80,}/i, /fromCharCode\\([^)]{200,}/i, /[A-Za-z0-9+/=]{200,}/i], text)) {\n    findings.push({ rule: \"obfuscation\", severity: \"medium\", detail: \"possible obfuscated blob (\" + path + \")\" });\n  }\n  const urls = scanNetworkUrls(text, path);\n  findings.push(...urls);\n  const envRead = /process\\.env\\s*\\[/.test(text) || /process\\.env\\.[A-Za-z_]+/.test(text);\n  const exfil = urls.some((f) => f.severity === \"high\" || f.severity === \"medium\");\n  if (envRead && exfil) {\n    findings.push({ rule: \"env-exfil\", severity: \"high\", detail: \"reads process.env and sends data to a non-allowlisted host (\" + path + \")\" });\n  }\n  if (envRead && !exfil) {\n    findings.push({ rule: \"env-read\", severity: \"info\", detail: \"reads process.env (\" + path + \")\" });\n  }\n  return findings;\n}\n\n/** Run every scanner over a set of files; produce findings + a trust score. */\nexport function runSecurityScan(files) {\n  const findings = [];\n  for (const file of files) {\n    const { path, text } = file;\n    if (!text) continue;\n    if (/package\\.json$/.test(path)) findings.push(...scanManifest(text, path));\n    else if (/\\.(sh|bash|zsh)$/.test(path) || path.startsWith(\"scripts/\")) findings.push(...scanShell(text, path));\n    else if (/\\.(js|cjs|mjs|ts|mts|cts)$/.test(path)) findings.push(...scanSource(text, path));\n    else findings.push(...scanNetworkUrls(text, path));\n  }\n  const seen = new Set();\n  const unique = findings.filter((f) => {\n    const k = f.rule + \"|\" + f.severity + \"|\" + f.detail;\n    if (seen.has(k)) return false;\n    seen.add(k);\n    return true;\n  });\n  const order = { critical: 0, high: 1, medium: 2, low: 3, info: 4 };\n  unique.sort((a, b) => (order[a.severity] ?? 9) - (order[b.severity] ?? 9));\n  const trustScore = Math.max(0, 100 - unique.reduce((acc, f) => acc + (SEVERITY_WEIGHT[f.severity] ?? 1), 0));\n  return { findings: unique, trustScore };\n}\n\n/** True when any finding would veto the grade. */\nexport function hasVetoFinding(findings) {\n  return findings.some((f) => f.severity === \"critical\" || f.severity === \"high\");\n}\n"
    },
    {
      "path": "lib/scoring.js",
      "content": "/**\n * dsh-plugin-audit — v0.1 scoring model.\n *\n * Every plugin gets a 0-100 health score across four signals:\n *\n *   maintenance (30)  last push recency + star tier (archived → 0 + flag)\n *   docs        (25)  README presence + description depth + license\n *   npm         (30)  npm package exists + publish recency\n *   ecosystem   (15)  presence in the curated awesome list + listing recency\n *\n * A deep static security scan (exfiltration / credential / obfuscation /\n * persistence heuristics — the dsh-plugin-vetting space) is deliberately\n * NOT part of v0.1: scores must stay stable and explainable while the scan\n * pipeline lands. The `flags` array is the contract — a future security\n * tier pushes { kind: \"security\", severity: \"high\" } entries there, and any\n * high-severity flag caps the grade at D without rewiring the weights.\n *\n * Everything here is a pure function over plain records → unit-testable.\n */\n\nexport const WEIGHTS = { maintenance: 30, docs: 25, npm: 30, ecosystem: 15 };\n\nfunction daysSince(iso) {\n  if (!iso) return null;\n  const t = Date.parse(iso);\n  if (Number.isNaN(t)) return null;\n  return (Date.now() - t) / 86400000;\n}\n\n/**\n * Star trend from history snapshots [{date, stars}]. Returns null until at\n * least two snapshots exist with a measurable span. starsPerDay is the raw\n * daily growth rate between the first and last snapshot.\n */\nexport function computeStarTrend(snapshots) {\n  if (!Array.isArray(snapshots) || snapshots.length < 2) return null;\n  const list = snapshots\n    .filter((s) => typeof s?.stars === \"number\" && typeof s?.date === \"string\")\n    .sort((a, b) => a.date.localeCompare(b.date));\n  if (list.length < 2) return null;\n  const first = list[0];\n  const last = list[list.length - 1];\n  const days = Math.max(1, (Date.parse(last.date) - Date.parse(first.date)) / 86400000);\n  if (!Number.isFinite(days)) return null;\n  const deltaStars = last.stars - first.stars;\n  return {\n    firstDate: first.date,\n    lastDate: last.date,\n    periodDays: Math.round(days),\n    deltaStars,\n    starsPerDay: deltaStars / days,\n  };\n}\n\n/** Maintenance signal: recency of last push (0-20) + star tier (0-10). */\nexport function maintenanceScore(record) {\n  if (record.archived === true) return { points: 0, notes: [\"repo archived\"] };\n  const notes = [];\n  const sincePush = daysSince(record.pushedAt);\n  let points = 0;\n  if (sincePush === null) {\n    notes.push(\"last push unknown\");\n  } else if (sincePush < 30) {\n    points = 20; notes.push(\"pushed within 30 days\");\n  } else if (sincePush < 90) {\n    points = 15; notes.push(\"pushed within 90 days\");\n  } else if (sincePush < 180) {\n    points = 10; notes.push(\"pushed within 180 days\");\n  } else if (sincePush < 365) {\n    points = 5; notes.push(\"no push in the last year\");\n  } else {\n    points = 0; notes.push(\"dormant — no push for over a year\");\n  }\n  const stars = typeof record.stars === \"number\" ? record.stars : null;\n  if (stars === null) {\n    notes.push(\"stars unknown\");\n  } else if (stars >= 1000) {\n    points += 10; notes.push(stars + \" stars\");\n  } else if (stars >= 500) {\n    points += 8; notes.push(stars + \" stars\");\n  } else if (stars >= 100) {\n    points += 6; notes.push(stars + \" stars\");\n  } else if (stars >= 10) {\n    points += 4; notes.push(stars + \" stars\");\n  } else {\n    points += 2; notes.push(\"under 10 stars\");\n  }\n  // Star trend (needs >=2 sync snapshots): momentum adjusts the signal.\n  const trend = record.starTrend ?? null;\n  if (trend) {\n    if (trend.starsPerDay >= 0.5) { points += 4; notes.push(\"fast star growth (\" + trend.starsPerDay.toFixed(2) + \"/day)\"); }\n    else if (trend.starsPerDay >= 0.1) { points += 2; notes.push(\"steady star growth\"); }\n    else if (trend.starsPerDay <= -0.05) { points -= 3; notes.push(\"star count declining (\" + trend.starsPerDay.toFixed(2) + \"/day)\"); }\n    else { notes.push(\"star count flat\"); }\n  }\n  return { points: Math.max(0, Math.min(30, points)), notes };\n}\n\n/** Docs signal: README (0-12) + description depth (0-8) + license (0-5). */\nexport function docsScore(record) {\n  const notes = [];\n  let points = 0;\n  if (record.hasReadme === true) { points += 12; notes.push(\"README present\"); }\n  else if (record.hasReadme === false) { points += 0; notes.push(\"no README\"); }\n  else { points += 4; notes.push(\"README not probed yet\"); }\n  const desc = (record.description ?? \"\").trim();\n  if (desc.length >= 120) { points += 8; notes.push(\"detailed description\"); }\n  else if (desc.length >= 40) { points += 6; notes.push(\"decent description\"); }\n  else if (desc.length > 0) { points += 3; notes.push(\"short description\"); }\n  else { points += 0; notes.push(\"no description\"); }\n  if (record.license) { points += 5; notes.push(\"license: \" + record.license); }\n  else { notes.push(\"no license detected\"); }\n  return { points: Math.min(25, points), notes };\n}\n\n/** npm signal: package exists (0-10) + publish recency (0-14) + weekly downloads (0-6) = 30. */\nexport function npmScore(record) {\n  const notes = [];\n  const npm = record.npm;\n  if (!npm || npm.exists !== true) {\n    notes.push(\"no npm package found (GitHub-only install still works)\");\n    return { points: 3, notes };\n  }\n  let points = 10;\n  notes.push(\"npm package: \" + npm.name + \"@\" + (npm.version ?? \"?\"));\n  const sincePublish = daysSince(npm.publishedAt);\n  if (sincePublish === null) {\n    notes.push(\"publish date unknown\");\n    points += 4;\n  } else if (sincePublish < 90) {\n    points += 14; notes.push(\"published within 90 days\");\n  } else if (sincePublish < 365) {\n    points += 10; notes.push(\"published within a year\");\n  } else {\n    points += 4; notes.push(\"last publish over a year ago\");\n  }\n  if (npm.dshBundle === true) {\n    notes.push(\"npm package declares dsh.bundle (installable via dsh plugin add)\");\n  } else if (npm.dshBundle === false) {\n    notes.push(\"npm package lacks dsh.bundle declaration\");\n  }\n  const dl = typeof npm.weeklyDownloads === \"number\" ? npm.weeklyDownloads : null;\n  if (dl === null || dl <= 0) {\n    notes.push(\"no weekly download data\");\n  } else if (dl >= 1000) {\n    points += 6; notes.push(\"weekly downloads \" + dl);\n  } else if (dl >= 100) {\n    points += 4; notes.push(\"weekly downloads \" + dl);\n  } else {\n    points += 2; notes.push(\"weekly downloads \" + dl);\n  }\n  return { points: Math.min(30, points), notes };\n}\n\n/** Ecosystem signal: curated listing (0-12) + listing recency (0-3). */\nexport function ecosystemScore(record) {\n  const notes = [];\n  let points = 0;\n  if (record.curated === true) { points += 12; notes.push(\"in the curated awesome list\"); }\n  else { notes.push(\"not in the curated list\"); }\n  const sinceAdded = daysSince(record.addedAt);\n  if (sinceAdded !== null && sinceAdded < 90) {\n    points += 3; notes.push(\"listed recently\");\n  }\n  return { points: Math.min(15, points), notes };\n}\n\n/** Compute the full report card for a record. Pure. */\nexport function scoreRecord(record) {\n  const flags = [];\n  if (record.archived === true) flags.push({ kind: \"archived\", severity: \"high\", detail: \"repository is archived\" });\n  if (record.gone === true) flags.push({ kind: \"gone\", severity: \"high\", detail: \"repository returned 404\" });\n  // Security findings from the static scan (v0.2): high/critical veto the grade.\n  for (const f of record.security?.findings ?? []) {\n    if (f.severity === \"critical\" || f.severity === \"high\") {\n      flags.push({ kind: \"security\", severity: \"high\", detail: (f.rule ?? \"security\") + \": \" + (f.detail ?? \"\") });\n    }\n  }\n  // Plugin-structure verification (v0.4): after a deep scan, a repo with NO\n  // cordis.patch.yml / dsh.bundle / plugin entry is likely topic-tag farming.\n  const st = record.structure;\n  if (st && st.checkedAt && st.dshEvidence === false) {\n    flags.push({ kind: \"not-plugin\", severity: \"medium\", detail: \"no DSH plugin structure (no cordis.patch.yml / dsh.bundle / plugin entry) — possible topic-tag farming\" });\n  }\n\n  const maintenance = maintenanceScore(record);\n  const docs = docsScore(record);\n  const npm = npmScore(record);\n  const ecosystem = ecosystemScore(record);\n  const total = maintenance.points + docs.points + npm.points + ecosystem.points;\n\n  const breakdown = {\n    maintenance: { weight: WEIGHTS.maintenance, points: maintenance.points, notes: maintenance.notes },\n    docs: { weight: WEIGHTS.docs, points: docs.points, notes: docs.notes },\n    npm: { weight: WEIGHTS.npm, points: npm.points, notes: npm.notes },\n    ecosystem: { weight: WEIGHTS.ecosystem, points: ecosystem.points, notes: ecosystem.notes },\n  };\n\n  const hasHighFlag = flags.some((f) => f.severity === \"high\");\n  const hasMediumCap = flags.some((f) => f.kind === \"not-plugin\");\n  const grade = hasHighFlag ? \"D\" : hasMediumCap ? \"C\" : total >= 80 ? \"A\" : total >= 60 ? \"B\" : total >= 40 ? \"C\" : \"D\";\n  return {\n    total,\n    grade,\n    breakdown,\n    flags,\n    scoredAt: new Date().toISOString(),\n    version: 1,\n  };\n}\n\nexport function gradeBadge(grade) {\n  return { A: \"🛡️\", B: \"✅\", C: \"⚠️\", D: \"🚨\" }[grade] ?? \"❓\";\n}\n"
    },
    {
      "path": "lib/storage.js",
      "content": "/**\n * dsh-plugin-audit — local JSON storage for the plugin catalog.\n *\n * All state lives in a single data directory (config `dataDir`, default\n * \\$DSH_HOME/dsh-plugin-audit or ~/.dsh/dsh-plugin-audit) as three files:\n *   catalog.json  — one record per plugin repo (array, keyed by `repo`)\n *   meta.json     — sync state (last sync, counts, rate-limit residue)\n *   history.json  — rolling star snapshots per repo (trends for later tiers)\n *\n * Writes are atomic (temp file + rename) so a crash never truncates the\n * catalog. Records are upserted; never silently deleted — a vanished repo is\n * marked with `gone: true` so the leaderboard can still explain itself.\n */\nimport { mkdirSync, readFileSync, writeFileSync, renameSync, existsSync } from \"node:fs\";\nimport { join } from \"node:path\";\nimport { homedir } from \"node:os\";\n\nexport const DATA_VERSION = 1;\nexport const HISTORY_CAP = 60;\n\nfunction defaultDataDir() {\n  if (process.env.DSH_HOME) return join(process.env.DSH_HOME, \"dsh-plugin-audit\");\n  return join(homedir(), \".dsh\", \"dsh-plugin-audit\");\n}\n\nexport function normalizeDataDir(dataDir) {\n  return dataDir && dataDir.trim().length > 0 ? dataDir : defaultDataDir();\n}\n\nexport class Storage {\n  constructor(dataDir) {\n    this.dir = normalizeDataDir(dataDir);\n    this.catalogPath = join(this.dir, \"catalog.json\");\n    this.metaPath = join(this.dir, \"meta.json\");\n    this.historyPath = join(this.dir, \"history.json\");\n    this.scoresPath = join(this.dir, \"scores.json\");\n  }\n\n  ensureDir() {\n    mkdirSync(this.dir, { recursive: true });\n    return this;\n  }\n\n  readJson(path, fallback) {\n    try {\n      if (!existsSync(path)) return fallback;\n      return JSON.parse(readFileSync(path, \"utf8\"));\n    } catch {\n      return fallback; // corrupt file → start fresh, never crash the plugin\n    }\n  }\n\n  writeJson(path, value) {\n    this.ensureDir();\n    const tmp = path + \".tmp\";\n    writeFileSync(tmp, JSON.stringify(value, null, 1) + \"\\n\", \"utf8\");\n    renameSync(tmp, path);\n  }\n\n  loadCatalog() {\n    const raw = this.readJson(this.catalogPath, []);\n    return Array.isArray(raw) ? raw : [];\n  }\n\n  saveCatalog(records) {\n    this.writeJson(this.catalogPath, records);\n  }\n\n  loadMeta() {\n    return this.readJson(this.metaPath, {\n      version: DATA_VERSION,\n      lastSyncAt: null,\n      lastSyncStatus: null,\n      counts: { total: 0, npmFound: 0, curated: 0, gone: 0 },\n      rateLimit: null,\n    });\n  }\n\n  saveMeta(meta) {\n    this.writeJson(this.metaPath, meta);\n  }\n\n  loadHistory() {\n    const raw = this.readJson(this.historyPath, {});\n    return typeof raw === \"object\" && raw !== null ? raw : {};\n  }\n\n  /** Score-history timelines (one array per repo) for audit_history. */\n  loadScores() {\n    const raw = this.readJson(this.scoresPath, {});\n    return typeof raw === \"object\" && raw !== null ? raw : {};\n  }\n\n  saveScores(history) {\n    this.writeJson(this.scoresPath, history);\n  }\n\n  /** Record a star snapshot; keeps the most recent HISTORY_CAP per repo. */\n  appendStars(repo, stars, date) {\n    if (typeof stars !== \"number\") return;\n    const history = this.loadHistory();\n    const list = history[repo] ?? [];\n    const last = list[list.length - 1];\n    if (last && last.date === date && last.stars === stars) return; // idempotent\n    list.push({ date, stars });\n    if (list.length > HISTORY_CAP) list.splice(0, list.length - HISTORY_CAP);\n    history[repo] = list;\n    this.writeJson(this.historyPath, history);\n  }\n\n  /** Record many star snapshots in a single read/write (full sync sweeps). */\n  appendStarsBatch(entries) {\n    const history = this.loadHistory();\n    let changed = false;\n    for (const { repo, stars, date } of entries) {\n      if (typeof stars !== \"number\" || typeof repo !== \"string\") continue;\n      const list = history[repo] ?? [];\n      const last = list[list.length - 1];\n      if (last && last.date === date && last.stars === stars) continue;\n      list.push({ date, stars });\n      if (list.length > HISTORY_CAP) list.splice(0, list.length - HISTORY_CAP);\n      history[repo] = list;\n      changed = true;\n    }\n    if (changed) this.writeJson(this.historyPath, history);\n  }\n\n  /**\n   * Upsert records into the catalog. Existing entries keep their old values\n   * for any field the fresh record does not carry (never lose data on a\n   * failed probe); fresh values win. `onMerged` receives (repo, record).\n   */\n  mergeRecords(freshRecords, onMerged) {\n    const catalog = this.loadCatalog();\n    const byRepo = new Map(catalog.map((r) => [r.repo, r]));\n    let added = 0;\n    let updated = 0;\n    for (const fresh of freshRecords) {\n      if (!fresh || typeof fresh.repo !== \"string\" || fresh.repo.length === 0) continue;\n      const prev = byRepo.get(fresh.repo);\n      if (!prev) {\n        byRepo.set(fresh.repo, fresh);\n        added += 1;\n      } else {\n        const merged = { ...prev, ...fresh, npm: fresh.npm !== undefined ? fresh.npm : prev.npm };\n        byRepo.set(fresh.repo, merged);\n        updated += 1;\n      }\n      onMerged?.(fresh.repo, byRepo.get(fresh.repo));\n    }\n    const records = [...byRepo.values()];\n    this.saveCatalog(records);\n    return { added, updated, total: records.length };\n  }\n\n  getSummary() {\n    const catalog = this.loadCatalog();\n    const meta = this.loadMeta();\n    const scored = catalog.filter((r) => r.score && r.score.total !== null).length;\n    const withNpm = catalog.filter((r) => r.npm).length;\n    const flagged = catalog.filter((r) => (r.flags?.length ?? 0) > 0).length;\n    return {\n      total: catalog.length,\n      scored,\n      withNpm,\n      flagged,\n      curated: catalog.filter((r) => r.curated).length,\n      gone: catalog.filter((r) => r.gone).length,\n      lastSyncAt: meta.lastSyncAt,\n      lastSyncStatus: meta.lastSyncStatus,\n      rateLimit: meta.rateLimit,\n    };\n  }\n}\n"
    },
    {
      "path": "test/scanner.test.mjs",
      "content": "import test from \"node:test\";\nimport assert from \"node:assert/strict\";\nimport { applyScanToRecord, pickFiles } from \"../lib/scanner.js\";\n\ntest(\"applyScanToRecord: detects plugin structure from tree + package.json\", () => {\n  const record = {};\n  const scan = {\n    files: [{ path: \"package.json\", text: JSON.stringify({ name: \"x\", dsh: { bundle: { patch: \"./cordis.patch.yml\" } } }) }],\n    tree: [\"package.json\", \"cordis.patch.yml\", \"lib/index.js\", \"README.md\"],\n    result: { findings: [], trustScore: 100 },\n    hasReadme: true,\n  };\n  applyScanToRecord(record, scan);\n  assert.equal(record.structure.hasBundle, true);\n  assert.equal(record.structure.hasPatch, true);\n  assert.equal(record.structure.hasEntry, true);\n  assert.equal(record.structure.dshEvidence, true);\n});\n\ntest(\"applyScanToRecord: repo without plugin files is flagged as non-plugin\", () => {\n  const record = {};\n  const scan = {\n    files: [{ path: \"package.json\", text: JSON.stringify({ name: \"x\", main: \"index.js\" }) }],\n    tree: [\"package.json\", \"README.md\"],\n    result: { findings: [], trustScore: 100 },\n    hasReadme: true,\n  };\n  applyScanToRecord(record, scan);\n  assert.equal(record.structure.dshEvidence, false);\n  assert.equal(record.structure.hasBundle, false);\n  assert.equal(record.structure.hasPatch, false);\n});\n\ntest(\"pickFiles prioritizes package.json and entries\", () => {\n  const picked = pickFiles([\"README.md\", \"package.json\", \"lib/index.js\", \"scripts/install.sh\", \"src/other.ts\"]);\n  assert.ok(picked.includes(\"package.json\"));\n  assert.ok(picked.includes(\"lib/index.js\"));\n});\n"
    },
    {
      "path": "lib/client.js",
      "content": "/**\n * dsh-plugin-audit — browser face: a leaderboard dock above the composer,\n * rendered from the `auditSummary` session projection.\n *\n * Mirrors the loader format emitted by in-repo client bundles\n * (window.__ModuleLoader__.load with a CommonJS factory), served via the\n * client-modules roster (/plugins/<id>/client.js) on web profiles. React is\n * resolved through the app's module table; no JSX, no bundler, no TS.\n */\nwindow.__ModuleLoader__.load({\n  id: \"dsh-plugin-audit/client\",\n  factory: (require) => {\n    var module = { exports: {} };\n    var exports = module.exports;\n    Object.defineProperty(exports, Symbol.toStringTag, { value: \"Module\" });\n    var react = require(\"react\");\n\n    var cssId = \"dsh-plugin-audit/client\";\n    var css = [\n      \".dspa-dock{box-sizing:border-box;width:100%;max-width:calc(var(--dsh-composer-card-max-width) - 4 * var(--dsh-composer-dock-inset));margin:0 auto;border:1px solid var(--dsw-alias-border-l1);background:var(--dsw-specific-tip);border-radius:12px;padding:8px 12px;font-size:12px;line-height:18px;color:var(--dsw-alias-label-primary)}\",\n      \".dspa-head{font-weight:500;margin-bottom:4px;color:var(--dsw-alias-label-secondary)}\",\n      \".dspa-row{display:flex;gap:6px;align-items:baseline;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\",\n      \".dspa-repo{overflow:hidden;text-overflow:ellipsis;flex:1}\",\n      \".dspa-meta{color:var(--dsw-alias-label-caption);font-size:11px}\",\n      \".dspa-empty{color:var(--dsw-alias-label-caption)}\",\n      \".dspa-badge{font-weight:600}\",\n    ].join(\"\");\n    if (typeof document !== \"undefined\" && document.querySelector(\"style[data-plugin-css=\\\"\" + cssId + \"\\\"]\") === null) {\n      var tag = document.createElement(\"style\");\n      tag.dataset.plugin = \"dsh-plugin-audit\";\n      tag.dataset.pluginCss = cssId;\n      tag.textContent = css;\n      document.head.appendChild(tag);\n    }\n\n    var BADGE = { A: \"🛡️\", B: \"✅\", C: \"⚠️\", D: \"🚨\" };\n\n    function fmtDate(iso) {\n      if (!iso) return \"never\";\n      try { return new Date(iso).toLocaleString(); } catch { return String(iso); }\n    }\n\n    /** Leaderboard dock: catalog summary + top scored plugins. */\n    function AuditPanel(props) {\n      var useProjection = props.useProjection;\n      var projection = useProjection(\"auditSummary\");\n      if (projection == null) {\n        return react.createElement(\"div\", { className: \"dspa-dock\", \"data-audit-panel\": true },\n          react.createElement(\"div\", { className: \"dspa-empty\" }, \"Plugin audit: catalog unavailable.\"));\n      }\n      var rows = [];\n      if (projection.total === 0) {\n        rows.push(react.createElement(\"div\", { key: \"empty\", className: \"dspa-empty\" },\n          \"插件体检：目录为空 — 让 Agent 运行 audit_sync 同步 GitHub dsh-plugin 生态。\"));\n      } else {\n        var top = (projection.top || []).map(function (r) {\n          return react.createElement(\"div\", { key: r.repo, className: \"dspa-row\" },\n            react.createElement(\"span\", { className: \"dspa-badge\" }, r.grade ? (BADGE[r.grade] || \"❓\") + \" \" + r.grade : \"? \"),\n            react.createElement(\"span\", { className: \"dspa-repo\" }, r.repo),\n            react.createElement(\"span\", { className: \"dspa-meta\" }, (r.score != null ? r.score + \"/100\" : \"\") + (r.stars != null ? \" · \" + r.stars + \"★\" : \"\") + (r.category ? \" · \" + r.category : \"\")));\n        });\n        rows.push(react.createElement(\"div\", { key: \"counts\", className: \"dspa-meta\" },\n          projection.total + \" 插件 · \" + projection.scored + \" 已评分 · \" + projection.withNpm + \" 有 npm 包 · \" + projection.flagged + \" 带警示 · 上次同步 \" + fmtDate(projection.lastSyncAt)));\n        rows = rows.concat(top);\n      }\n      return react.createElement(\"div\", { className: \"dspa-dock\", \"data-audit-panel\": true },\n        react.createElement(\"div\", { className: \"dspa-head\" }, \"🩺 DSH 插件体检\"),\n        rows);\n    }\n\n    /** Browser plugin body: register the dock entry into the composer dock. */\n    function apply(ctx) {\n      ctx.slots.inject(\"conversation.input.dock\", function () {\n        return ctx.slots.register({\n          name: \"conversation.input.dock\",\n          id: \"audit-leaderboard\",\n          order: 40,\n        }, AuditPanel);\n      });\n    }\n\n    exports.name = \"audit-ui\";\n    exports.apply = apply;\n    exports.inject = [\"@deepseek-ai/dsh-client-runtime\"];\n    return module.exports;\n  },\n});\n"
    }
